INSERT [dbo].[BlogPosts] ([BlogPostId], [CategoryId], [AuthorUserId], [Title], [Slug], [Summary], [Content], [ThumbnailUrl], [VideoUrl], [Status], [IsFeatured], [ViewCount], [PublishedAt], [CreatedAt], [UpdatedAt], [PostType], [RejectionReason], [ApprovedByUserId], [ApprovedAt]) VALUES (1, 6, 3, N'Điều trị viêm tủy răng như thế nào? Dấu hiệu và quy trình chuẩn y khoa', N'dieu-tri-viem-tuy-rang-nhu-the-nao', N'Tủy răng được ví như "trái tim" nuôi dưỡng sự sống của chiếc răng. Khi bị viêm tủy, người bệnh thường chịu đựng những cơn đau nhức dữ dội từng cơn, đặc biệt về ban đêm. Cùng tìm hiểu nguyên nhân, dấu hiệu nhận biết và quy trình điều trị viêm tủy răng chuẩn y khoa, an toàn, không đau tại phòng khám.', N'<p class="lead"><strong>Tủy răng</strong> được ví như "trái tim" nuôi dưỡng sự sống của chiếc răng. Khi bị viêm tủy, người bệnh thường chịu đựng những cơn đau nhức dữ dội từng cơn, đặc biệt về ban đêm.</p><p>Tại DentalCare, quy trình điều trị tủy được thực hiện bằng hệ thống máy định vị chóp hiện đại và trâm xoay NiTi linh hoạt, giúp làm sạch ống tủy nhanh chóng, triệt để và hoàn toàn êm ái.</p>', N'https://res.cloudinary.com/demo/image/upload/v1/dental/viem-tuy-rang-banner.jpg', NULL, N'Published', 1, 343, CAST(N'2026-10-26T15:40:22.1394536' AS DateTime2), CAST(N'2026-10-26T15:40:22.1394536' AS DateTime2), NULL, N'Blog', NULL, NULL, NULL)
INSERT [dbo].[BlogPosts] ([BlogPostId], [CategoryId], [AuthorUserId], [Title], [Slug], [Summary], [Content], [ThumbnailUrl], [VideoUrl], [Status], [IsFeatured], [ViewCount], [PublishedAt], [CreatedAt], [UpdatedAt], [PostType], [RejectionReason], [ApprovedByUserId], [ApprovedAt]) VALUES (2, 6, 3, N'Nhổ răng khôn mọc lệch khi nào? Quy trình nhổ răng không đau bằng công nghệ Piezotome', N'nho-rang-khon-moc-lech-khi-nao-quy-trinh-nho-rang-khong-dau', N'Răng khôn (răng số 8) mọc lệch, mọc ngầm thường gây sưng đau, sốt, viêm lợi trùm và phá hủy răng số 7 kề bên. Cùng tìm hiểu thời điểm vàng nên nhổ răng khôn và công nghệ nhổ răng siêu âm Piezotome giúp giảm chấn thương, hạn chế chảy máu và nhanh hồi phục.', N'<p class="lead"><strong>Răng khôn (răng số 8)</strong> mọc lệch, mọc ngầm là nỗi ám ảnh của nhiều người bởi những cơn đau nhức kéo dài, sưng má và khó há miệng.</p><p>Công nghệ nhổ răng sóng siêu âm Piezotome sử dụng bước sóng siêu âm chọn lọc để bóc tách mô nướu nhẹ nhàng mà không làm tổn thương xương ổ răng và dây thần kinh, giúp lành thương nhanh chóng.</p>', N'https://res.cloudinary.com/demo/image/upload/v1/dental/nho-rang-khon-banner.jpg', NULL, N'Published', 1, 258, CAST(N'2026-10-24T15:40:22.1461912' AS DateTime2), CAST(N'2026-10-24T15:40:22.1461912' AS DateTime2), NULL, N'Blog', NULL, NULL, NULL)
INSERT [dbo].[BlogPosts] ([BlogPostId], [CategoryId], [AuthorUserId], [Title], [Slug], [Summary], [Content], [ThumbnailUrl], [VideoUrl], [Status], [IsFeatured], [ViewCount], [PublishedAt], [CreatedAt], [UpdatedAt], [PostType], [RejectionReason], [ApprovedByUserId], [ApprovedAt]) VALUES (3, 2, 3, N'Cấy ghép Implant nha khoa: Giải pháp phục hồi răng đã mất hoàn hảo nhất hiện nay', N'cay-ghep-implant-nha-khoa-giai-phap-phuc-hoi-rang-da-mat', N'Mất răng không chỉ ảnh hưởng đến thẩm mỹ và chức năng ăn nhai mà còn dẫn đến tiêu xương hàm, lão hóa cơ mặt. Cấy ghép Implant là kỹ thuật hiện đại duy nhất phục hồi trọn vẹn cả chân răng và thân răng, mang lại cảm giác ăn nhai vững chắc như răng thật.', N'<p class="lead"><strong>Cấy ghép Implant</strong> là giải pháp phục hình răng đã mất tiên tiến nhất hiện nay, mang lại độ bền chắc trọn đời và khôi phục 100% lực ăn nhai như răng thật.</p><p>DentalCare sử dụng các dòng trụ Implant hàng đầu thế giới từ Thụy Sĩ, Mỹ và Hàn Quốc với tỷ lệ tích hợp xương thành công lên tới 99.8%.</p>', N'https://res.cloudinary.com/demo/image/upload/v1/dental/implant-banner.jpg', NULL, N'Published', 1, 512, CAST(N'2026-10-22T15:40:22.1461912' AS DateTime2), CAST(N'2026-10-22T15:40:22.1461912' AS DateTime2), NULL, N'Blog', NULL, NULL, NULL)
INSERT [dbo].[BlogPosts] ([BlogPostId], [CategoryId], [AuthorUserId], [Title], [Slug], [Summary], [Content], [ThumbnailUrl], [VideoUrl], [Status], [IsFeatured], [ViewCount], [PublishedAt], [CreatedAt], [UpdatedAt], [PostType], [RejectionReason], [ApprovedByUserId], [ApprovedAt]) VALUES (4, 1, 3, N'Niềng răng mắc cài hay máng trong suốt Invisalign: Nên chọn phương pháp nào?', N'nieng-rang-mac-cai-hay-invisalign-nen-chon-phuong-phap-nao', N'Bạn đang phân vân giữa niềng răng mắc cài truyền thống và niềng răng khay trong suốt Invisalign? Bài viết phân tích chi tiết ưu nhược điểm, chi phí và hiệu quả của từng phương pháp giúp bạn dễ dàng đưa ra quyết định phù hợp nhất.', N'<p class="lead">Sở hữu một hàm răng đều đặn cùng nụ cười rạng rỡ là mong muốn của tất cả mọi người. Tuy nhiên, lựa chọn giữa niềng răng mắc cài hay khay trong suốt Invisalign luôn là thắc mắc lớn.</p><p>Hãy cùng các chuyên gia chỉnh nha tại DentalCare so sánh chi tiết ưu nhược điểm của từng phương pháp để tìm ra giải pháp tối ưu nhất cho bạn.</p>', N'https://res.cloudinary.com/demo/image/upload/v1/dental/nieng-rang-banner.jpg', NULL, N'Published', 0, 189, CAST(N'2026-10-20T15:40:22.1480161' AS DateTime2), CAST(N'2026-10-20T15:40:22.1480161' AS DateTime2), NULL, N'Blog', NULL, NULL, NULL)
INSERT [dbo].[BlogPosts] ([BlogPostId], [CategoryId], [AuthorUserId], [Title], [Slug], [Summary], [Content], [ThumbnailUrl], [VideoUrl], [Status], [IsFeatured], [ViewCount], [PublishedAt], [CreatedAt], [UpdatedAt], [PostType], [RejectionReason], [ApprovedByUserId], [ApprovedAt]) VALUES (5, 5, 3, N'Hướng dẫn chăm sóc răng miệng đúng cách: 6 thói quen bảo vệ nụ cười khỏe đẹp', N'huong-dan-cham-soc-rang-mieng-dung-cach-6-thoi-quen', N'Đánh răng 2 lần mỗi ngày đã thực sự đủ để bảo vệ hàm răng của bạn khỏi sâu răng và viêm nướu? Khám phá 6 thói quen chăm sóc răng miệng chuẩn nha khoa từ việc chải răng đúng kỹ thuật Bass đến sử dụng chỉ nha khoa và máy tăm nước.', N'<p class="lead">Một nụ cười khỏe đẹp bắt nguồn từ những thói quen vệ sinh răng miệng đúng cách mỗi ngày.</p><p>Đừng bỏ qua 6 bước chăm sóc chuẩn y khoa được khuyến cáo bởi Hiệp hội Nha khoa Quốc tế để duy trì hàm răng sáng khỏe suốt đời.</p>', N'https://res.cloudinary.com/demo/image/upload/v1/dental/cham-soc-rang-banner.jpg', NULL, N'Published', 0, 145, CAST(N'2026-10-18T15:40:22.1480161' AS DateTime2), CAST(N'2026-10-18T15:40:22.1480161' AS DateTime2), NULL, N'Blog', NULL, NULL, NULL)
INSERT [dbo].[BlogPosts] ([BlogPostId], [CategoryId], [AuthorUserId], [Title], [Slug], [Summary], [Content], [ThumbnailUrl], [VideoUrl], [Status], [IsFeatured], [ViewCount], [PublishedAt], [CreatedAt], [UpdatedAt], [PostType], [RejectionReason], [ApprovedByUserId], [ApprovedAt]) VALUES (12, 1, 2, N'Cẩm nang chăm sóc răng miệng sau khi nhổ răng khôn', N'cam-nang-cham-soc-rang-mieng-sau-khi-nho-rang-khon', N'Những lưu ý quan trọng cần biết trong 48 giờ đầu sau phẫu thuật nhổ răng khôn.', N'<p>Sau khi nhổ răng khôn, bệnh nhân cần cắn chặt bông gòn trong 45 phút đầu, chườm lạnh ngoài má trong ngày đầu tiên và không súc miệng bằng nước muối đậm đặc...</p>', NULL, NULL, N'Published', 1, 0, CAST(N'2026-11-09T10:37:59.4628011' AS DateTime2), CAST(N'2026-11-09T10:37:59.3322258' AS DateTime2), CAST(N'2026-11-09T10:37:59.4629072' AS DateTime2), N'Blog', NULL, 1, CAST(N'2026-11-09T10:37:59.4628613' AS DateTime2))
