INSERT [dbo].[ClinicalEntries] ([ClinicalEntryId], [MedicalRecordId], [AppointmentId], [DentistUserId], [Symptoms], [ClinicalFindings], [Diagnosis], [DentalConditions], [ClinicalNotes], [CreatedAt], [UpdatedAt]) VALUES (2, 2, 9, 3, N'Chảy máu nướu răng tự phát khi chải răng, có mùi hôi miệng.', N'Vôi răng dưới nướu nhiều toàn hàm, tụt nướu nhẹ 1-2mm vùng răng cửa hàm dưới, túi nha chu nông 3mm.', N'Viêm nha chu mạn tính độ 2 (K05.3), cao răng dưới nướu độ 3.', N'Nướu phù nề sưng đỏ viền quanh các kẽ răng.', N'Lấy cao răng toàn phần bằng máy siêu âm Woodpecker, đánh bóng toàn hàm bằng bột Proxyt, bơm rửa túi nha chu bằng Povidine 10%.', CAST(N'2026-10-12T10:10:00.0000000' AS DateTime2), NULL)
INSERT [dbo].[ClinicalEntries] ([ClinicalEntryId], [MedicalRecordId], [AppointmentId], [DentistUserId], [Symptoms], [ClinicalFindings], [Diagnosis], [DentalConditions], [ClinicalNotes], [CreatedAt], [UpdatedAt]) VALUES (3, 6, 13, 6, N'Răng ố vàng xỉn màu do uống trà, cà phê nhiều năm, mong muốn răng trắng sáng tự nhiên.', N'Màu răng ban đầu A3.5 (bảng so màu Vita), men răng chắc khỏe, không có lỗ sâu hoạt động.', N'Nhiễm màu ngoại sinh men răng do sắc tố thực phẩm độ 3.', N'Mô mềm săn chắc, đường cười cân đối.', N'Bảo vệ viền nướu bằng composite lỏng Gingival Barrier, quét thuốc tẩy trắng Opalescence Boost 40%, chiếu đèn Laser Beyond Whitening 3 chu kỳ x 15 phút. Nâng tông lên màu A1.', CAST(N'2026-10-12T09:55:00.0000000' AS DateTime2), NULL)
